BEGIN ATOMIC
 IF (SELECT count(*) FROM client_dev.ashlar_burst_20261005_k1.stage_1 s JOIN client_dev.ashlar_burst_20261005_k1.object_current o ON s.id=o.id WHERE o.id>0 AND o.id<=1000000 AND (o.props_json IS DISTINCT FROM s.props_json OR o.retained_json IS DISTINCT FROM s.retained_json OR o.entity_version<>s.entity_version))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar prior canonical mismatch'; END IF;
 MERGE INTO client_dev.ashlar_burst_20261005_k1.object_current t USING client_dev.ashlar_burst_20261005_k1.stage_1 s ON t.id=s.id AND t.id>0 AND t.id<=1000000 WHEN MATCHED THEN UPDATE SET t.props_json=s.new_props,t.entity_version=1,t.source_position=1,t.published_at=current_timestamp();
 INSERT INTO client_dev.ashlar_burst_20261005_k1.property_journal SELECT 'pilot','object',1,id,103,1,'update',true,substring(to_json(array(get_json_object(props_json,'$.103'))),2,length(to_json(array(get_json_object(props_json,'$.103'))))-2),true,substring(to_json(array(get_json_object(new_props,'$.103'))),2,length(to_json(array(get_json_object(new_props,'$.103'))))-2),'r1','S','e',1,id,'synthetic-batch:1',current_timestamp() FROM client_dev.ashlar_burst_20261005_k1.stage_1;
 IF (SELECT count(*) FROM client_dev.ashlar_burst_20261005_k1.stage_1 s JOIN client_dev.ashlar_burst_20261005_k1.object_current o ON s.id=o.id WHERE o.id>0 AND o.id<=1000000)<>1000000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar changed cardinality'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_burst_20261005_k1.stage_1 s JOIN client_dev.ashlar_burst_20261005_k1.object_current o ON s.id=o.id WHERE o.id>0 AND o.id<=1000000 AND (o.props_json<>s.new_props OR o.retained_json<>s.retained_json OR o.entity_version<>1))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar carrier mismatch'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_burst_20261005_k1.property_journal WHERE source_position=1)<>1000000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar journal count'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_burst_20261005_k1.property_journal j JOIN client_dev.ashlar_burst_20261005_k1.stage_1 s ON j.id=s.id WHERE j.source_position=1 AND (from_json(concat('[',j.old_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.props_json,'$.103') OR from_json(concat('[',j.new_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.new_props,'$.103')))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ashlar journal value'; END IF;
 INSERT INTO client_dev.ashlar_burst_20261005_k1.receipt VALUES (1,current_timestamp()); END
